/**
 * issue #16 worker bootstrap: composable role factories over the same
 * building blocks M6/M7 already proved (`bootstrap()`, `Capture`,
 * `createExecuteNode`, `@temporalio/worker` `Worker`), so node-red-temporal
 * can run as ONE combined process (today's default/compatibility behavior)
 * OR as two independently deployable/scaleable roles:
 *
 *   - a "workflow" Worker: registers `executeFlow` Workflow code only, never
 *     boots Node-RED, never calls `bootstrap()`/installs `Capture`.
 *   - an "activity" Worker: boots the live Node-RED runtime, installs
 *     `Capture`, owns source ingress, and polls only the Activity Task
 *     Queue for `executeNode`.
 *
 * `createCombinedWorker` composes both roles into one process (local/simple
 * operation, today's default). `createWorker()` is kept as a drop-in alias
 * for `createCombinedWorker` so M6/M7 callers/tests keep working unchanged.
 *
 * --- Known caveat: at-least-once Activity execution (A2 #1) ---
 * Temporal Activities are at-least-once. If the Activity-role worker is
 * killed while `executeNode` is mid-flight against a side-effecting node
 * (e.g. an `http request` node that already sent the HTTP call but the
 * process dies before the Activity resolves), Temporal WILL re-schedule and
 * re-run that same Activity invocation on worker restart, re-firing the
 * side effect. This is a known, documented limitation of the MVP recovery
 * model, not something this issue attempts to solve or hide.
 */

"use strict";

const { Worker, NativeConnection } = require("@temporalio/worker");
const { bootstrap } = require("./bootstrap");
const { Capture } = require("./capture");
const { createExecuteNode } = require("./activities");
const { extractWireGraph, extractNodeMeta } = require("./wireGraph");
// Same `@node-red/util` module bootstrap.js already uses for `redUtil.init`/
// `redUtil.events` - it exposes the `hooks` API Capture.install() needs, so
// no test-only helper (`nr-test-utils`) is pulled into production code.
const redUtil = require("../../../@node-red/util");

const WORKFLOWS_PATH = require.resolve("./workflows.js");

// Single default task queue, shared by both roles unless overridden - this
// is exactly today's pre-issue-16 combined-mode behavior (one queue, one
// process), preserved as the default so nothing existing regresses.
const DEFAULT_TASK_QUEUE = "node-red-temporal";
const DEFAULT_ADDRESS = "127.0.0.1:7233";
const DEFAULT_NAMESPACE = "default";

/**
 * issue #16 / #21: resolves normal Temporal configuration (address,
 * namespace, Workflow/Activity Task Queues, an optional pre-built
 * `Connection`) from explicit `options`, falling back to `TEMPORAL_ADDRESS`/
 * `TEMPORAL_NAMESPACE` env vars, then to today's local defaults. This is the
 * single place both the client (ingress-start) and the Worker's OWN poll
 * connection (`Worker.create({connection})`) read from, so the two can
 * never silently disagree (the root cause of issue #21).
 *
 * @param {object} [options]
 * @param {string} [options.address]
 * @param {string} [options.namespace]
 * @param {string} [options.workflowTaskQueue]
 * @param {string} [options.activityTaskQueue]
 * @returns {{address:string, namespace:string, workflowTaskQueue:string, activityTaskQueue:string}}
 */
function resolveTemporalConfig(options) {
    options = options || {};
    return {
        address: options.address || process.env.TEMPORAL_ADDRESS || DEFAULT_ADDRESS,
        namespace: options.namespace || process.env.TEMPORAL_NAMESPACE || DEFAULT_NAMESPACE,
        workflowTaskQueue: options.workflowTaskQueue || process.env.TEMPORAL_WORKFLOW_TASK_QUEUE || DEFAULT_TASK_QUEUE,
        activityTaskQueue: options.activityTaskQueue || process.env.TEMPORAL_ACTIVITY_TASK_QUEUE || DEFAULT_TASK_QUEUE
    };
}

/**
 * issue #21: lazily creates (once) and reuses a `@temporalio/client` `Client`
 * connected to the configured `address`/`namespace`, mirroring
 * `bin/node-red-temporal`'s `runStart` connection pattern.
 *
 * @param {{address:string, namespace:string}} temporalConfig
 * @returns {Promise<object>} a `@temporalio/client` `Client` instance
 */
async function connectClient(temporalConfig) {
    const { Client, Connection } = require("@temporalio/client");
    const connection = await Connection.connect({ address: temporalConfig.address });
    return new Client({ connection, namespace: temporalConfig.namespace });
}

/**
 * M3: maps one M2 ingress group (`{sourceNodeId, msg, sends}`) into an
 * `initial` pending-queue seed array of `{nodeId, msg}` - one entry per
 * `sends[]` item, using EACH send's own `msg` (not the group's top-level
 * `msg`), since fan-out branches could in principle carry per-destination
 * payloads even though today they're identical.
 *
 * @param {{sourceNodeId:string, msg:object, sends:Array<{port:number, destinationId:string, msg:object}>}} ingress
 * @returns {Array<{nodeId:string, msg:object}>}
 */
function toInitial(ingress) {
    return (ingress.sends || []).map((send) => ({ nodeId: send.destinationId, msg: send.msg }));
}

/**
 * M3/issue #16 (fixes #27): builds the `onIngress` callback wired into
 * `Capture`, which starts a real `executeFlow` Workflow Execution for every
 * autonomous source-node emission (e.g. a scheduled Inject firing on its
 * own - `done(false)` has already suppressed local routing for these inside
 * Capture itself, before this callback ever runs).
 *
 * issue #27 fix: the started Workflow now targets the CONFIGURED
 * `workflowTaskQueue` (not a hardcoded constant), and the Workflow itself is
 * given the configured `activityTaskQueue` so it schedules `executeNode`
 * onto the right queue for a decoupled deployment (issue #16 AC: "Node-RED
 * source ingress can start Workflows handled by a separate Workflow Worker
 * process").
 *
 * AC7: if `client.workflow.start()` throws/rejects, the error is caught and
 * logged clearly via `console.error` - it must never become an unhandled
 * rejection, and no false success may be reported. Since local routing is
 * already suppressed unconditionally by Capture, there is no fallback to
 * local Node-RED routing to guard against here; this handler's only job is
 * to make a start failure VISIBLE.
 *
 * @param {function(): Promise<object>} getClient - resolves to a connected `Client`
 * @param {({graph:object, nodeMeta:object, flowVersion:string}|function(): Promise<{graph:object, nodeMeta:object, flowVersion:string}>)} flowInfoOrGetter -
 *   either a static snapshot (legacy) or (issue #15) a function returning the
 *   CURRENT flow graph/nodeMeta/flowVersion, re-evaluated on every ingress so
 *   a headless `bootstrap().deploy()` redeploy is reflected without needing
 *   a new Worker.
 * @param {{workflowTaskQueue:string, activityTaskQueue:string}} temporalConfig
 * @returns {function(object): Promise<void>}
 */
function createOnIngress(getClient, flowInfoOrGetter, temporalConfig) {
    temporalConfig = temporalConfig || { workflowTaskQueue: DEFAULT_TASK_QUEUE, activityTaskQueue: DEFAULT_TASK_QUEUE };
    return async function onIngress(ingress) {
        const initial = toInitial(ingress);
        const workflowId = `ingress-${Date.now()}-${Math.random().toString(36).slice(2)}`;
        try {
            const flowInfo = typeof flowInfoOrGetter === "function" ? await flowInfoOrGetter() : flowInfoOrGetter;
            const client = await getClient();
            await client.workflow.start("executeFlow", {
                taskQueue: temporalConfig.workflowTaskQueue,
                workflowId,
                args: [{
                    graph: flowInfo.graph,
                    nodeMeta: flowInfo.nodeMeta,
                    flowVersion: flowInfo.flowVersion,
                    initial,
                    activityTaskQueue: temporalConfig.activityTaskQueue
                }]
            });
        } catch (err) {
            console.error(`[node-red-temporal] failed to start executeFlow workflow for source node "${ingress.sourceNodeId}": ${err && err.message ? err.message : err}`);
        }
    };
}

/**
 * Node-RED runtime role: boots the flow ONCE (nodes stay alive/wired for
 * the whole process lifetime, per the architecture rule) via `bootstrap()`.
 * Does NOT install `Capture` itself - only the Activity/Combined roles
 * (which need source ingress + Activity execution) do that, so a
 * Workflow-only role never even indirectly touches Node-RED/Capture.
 *
 * @param {string} flowFilePath
 * @param {object} [options]
 * @param {object} [options.bootstrapOptions] - forwarded to `bootstrap()`
 * @returns {Promise<{handle:object, currentFlowInfo:function(): Promise<object>, stop:function(): Promise<void>}>}
 */
async function createNodeRedRuntime(flowFilePath, options) {
    options = options || {};
    const handle = await bootstrap(flowFilePath, options.bootstrapOptions);

    // issue #15: graph/nodeMeta/flowVersion for ingress-started workflows
    // are sourced from the SAME bootstrap handle Node-RED's own runtime
    // maintains (`handle.getCurrentFlow()`/`handle.flowVersion`), not a
    // second independent `fs.readFileSync` of the flow file - so a headless
    // `handle.deploy()` redeploy (no process restart) is reflected in the
    // very next ingress without rebuilding/recreating this runtime.
    async function currentFlowInfo() {
        const flows = await handle.getCurrentFlow();
        return {
            graph: extractWireGraph(flows),
            nodeMeta: extractNodeMeta(flows),
            flowVersion: handle.flowVersion
        };
    }

    return {
        handle,
        currentFlowInfo,
        async stop() {
            await handle.stop();
        }
    };
}

/**
 * Activity role: hosts the live Node-RED runtime (via `createNodeRedRuntime`),
 * owns source ingress (installs `Capture` with the ingress-start wiring),
 * registers `executeNode`, and polls ONLY the configured Activity Task
 * Queue. This is the ONLY role that may boot Node-RED/install `Capture`/
 * originate source ingress (issue #16 requirement).
 *
 * @param {string} flowFilePath
 * @param {object} [options]
 * @param {object} [options.bootstrapOptions]
 * @param {object} [options.captureOptions]
 * @param {object} [options.workerOptions] - merged into `Worker.create()` options
 * @param {object} [options.temporal] - {address, namespace, workflowTaskQueue, activityTaskQueue}
 * @returns {Promise<{worker:Worker, handle:object, capture:object, flowVersion:string, temporalConfig:object, stop:function(): Promise<void>}>}
 */
async function createActivityWorker(flowFilePath, options) {
    options = options || {};
    const temporalConfig = resolveTemporalConfig(options.temporal);
    const runtime = await createNodeRedRuntime(flowFilePath, options);
    const handle = runtime.handle;

    // Client connection is lazy and memoized: NOT attempted at boot time
    // (the worker must still boot even if Temporal is unreachable), only on
    // the first actual ingress event, and reused across subsequent ones.
    //
    // issue #12 finding 2: a REJECTED connectClient() must not poison every
    // future ingress attempt for the rest of the worker's lifetime. Clearing
    // `clientPromise` in the `.catch()` means a failed attempt is retried on
    // the NEXT ingress event instead of returning the same rejected promise
    // forever; a successful client is still memoized/reused as before.
    let clientPromise;
    function getClient() {
        if (!clientPromise) {
            clientPromise = connectClient(temporalConfig).catch((err) => {
                clientPromise = undefined;
                throw err;
            });
        }
        return clientPromise;
    }

    const captureOptions = Object.assign(
        { onIngress: createOnIngress(getClient, runtime.currentFlowInfo, temporalConfig) },
        options.captureOptions || {}
    );
    const capture = new Capture(captureOptions);
    capture.install(redUtil);

    // issue #15: `flowVersion` is passed as a live getter (function),
    // re-read at EVERY Activity execution, instead of a scalar closed over
    // once at worker-boot time - so a `handle.deploy()` between Activity
    // executions is observed without recreating the Activity/Worker.
    const executeNode = createExecuteNode({
        getNode: handle.getNode,
        flowVersion: () => handle.flowVersion,
        capture
    });

    // issue #21 fix: the Worker's OWN poll connection now honors the
    // configured `address` too (previously only the ingress-start client
    // did) - a `NativeConnection` is established explicitly and handed to
    // `Worker.create({connection})` instead of silently relying on the SDK's
    // built-in localhost:7233 default.
    const connection = await NativeConnection.connect({ address: temporalConfig.address });

    const worker = await Worker.create(Object.assign(
        {
            connection,
            namespace: temporalConfig.namespace,
            workflowsPath: WORKFLOWS_PATH,
            activities: { executeNode },
            taskQueue: temporalConfig.activityTaskQueue
        },
        options.workerOptions || {}
    ));

    return {
        worker,
        handle,
        capture,
        flowVersion: handle.flowVersion,
        temporalConfig,
        async stop() {
            worker.shutdown();
            capture.uninstall();
            await handle.stop();
            await connection.close();
        }
    };
}

/**
 * Workflow role: registers `executeFlow` Workflow code ONLY. Never calls
 * `bootstrap()`, never touches Node-RED, never installs `Capture` - this is
 * the hard constraint from issue #16 ("Workflow-only Worker must never boot
 * sources or install Capture"). Polls ONLY the configured Workflow Task
 * Queue.
 *
 * @param {object} [options]
 * @param {object} [options.workerOptions] - merged into `Worker.create()` options
 * @param {object} [options.temporal] - {address, namespace, workflowTaskQueue, activityTaskQueue}
 * @returns {Promise<{worker:Worker, temporalConfig:object, stop:function(): Promise<void>}>}
 */
async function createWorkflowWorker(options) {
    options = options || {};
    const temporalConfig = resolveTemporalConfig(options.temporal);

    // issue #21 fix: same explicit `NativeConnection` as the Activity role,
    // so a Workflow-only Worker also honors the configured address instead
    // of the SDK's built-in localhost default.
    const connection = await NativeConnection.connect({ address: temporalConfig.address });

    const worker = await Worker.create(Object.assign(
        {
            connection,
            namespace: temporalConfig.namespace,
            workflowsPath: WORKFLOWS_PATH,
            taskQueue: temporalConfig.workflowTaskQueue
        },
        options.workerOptions || {}
    ));

    return {
        worker,
        temporalConfig,
        async stop() {
            worker.shutdown();
            await connection.close();
        }
    };
}

/**
 * Combined role (today's default/compatibility mode): a single process that
 * hosts Node-RED + Activities + Workflows. When `workflowTaskQueue` and
 * `activityTaskQueue` are left at their shared default, this is exactly
 * equivalent to the pre-issue-16 single-Worker/single-queue behavior; both
 * roles still run as two logical Workers composed in this one process so
 * the SAME code path backs the decomposed deployment shapes.
 *
 * @param {string} flowFilePath
 * @param {object} [options]
 * @returns {Promise<{worker:Worker, workflowWorker:object, handle:object, capture:object, flowVersion:string, temporalConfig:object, stop:function(): Promise<void>}>}
 */
async function createCombinedWorker(flowFilePath, options) {
    options = options || {};
    const activityWorker = await createActivityWorker(flowFilePath, options);

    // Same task queue by default (DEFAULT_TASK_QUEUE for both), so when the
    // caller never overrides workflowTaskQueue/activityTaskQueue this is a
    // single effective queue, matching the pre-issue-16 behavior byte for
    // byte (see worker_spec.js's existing `opts.taskQueue.should.equal
    // ("node-red-temporal")` assertion, still satisfied unchanged).
    const workflowOnlyOptions = Object.assign({}, options, {
        workerOptions: options.workerOptions,
        temporal: activityWorker.temporalConfig
    });
    const workflowWorker = activityWorker.temporalConfig.workflowTaskQueue === activityWorker.temporalConfig.activityTaskQueue
        // Same queue: the Activity Worker ALREADY registers workflowsPath
        // (see createActivityWorker) and polls that one queue - a second
        // Worker polling the identical queue would just double-poll, so
        // reuse the single Worker instead of creating a second one.
        ? null
        : await createWorkflowWorker(workflowOnlyOptions);

    return {
        worker: activityWorker.worker,
        workflowWorker,
        handle: activityWorker.handle,
        capture: activityWorker.capture,
        flowVersion: activityWorker.flowVersion,
        temporalConfig: activityWorker.temporalConfig,
        async stop() {
            if (workflowWorker) {
                await workflowWorker.stop();
            }
            await activityWorker.stop();
        }
    };
}

// Compatibility alias (M6/M7 callers/tests): `createWorker()` remains a
// drop-in name for the Combined role.
const createWorker = createCombinedWorker;

module.exports = {
    createWorker,
    createCombinedWorker,
    createActivityWorker,
    createWorkflowWorker,
    createNodeRedRuntime,
    resolveTemporalConfig,
    WORKFLOWS_PATH,
    toInitial,
    createOnIngress
};
